-- 资源目录在本脚本。初始授权在 FG_AUTH_ROLE_RESOURCE.sql，之后由角色页维护。
-- fg0100 是示例告警菜单，灌库时写入。页面在 web 路由里挂占位页。
CREATE TABLE IF NOT EXISTS `FG_AUTH_RESOURCE` (
  `resourceId` VARCHAR(100) NOT NULL COMMENT '资源ID，联合主键',
  `tenantId` VARCHAR(32) NOT NULL COMMENT '租户ID，联合主键',
  `resourceName` VARCHAR(100) NOT NULL COMMENT '资源名称',
  `resourceCode` VARCHAR(100) NOT NULL COMMENT '资源编码，程序按它鉴权',
  `resourceType` VARCHAR(20) NOT NULL COMMENT '资源类型(GROUP分组,MODULE模块,BUTTON按钮,API接口)',
  `resourcePath` VARCHAR(255) DEFAULT NULL COMMENT '菜单路径或 API 路径',
  `resourceMethod` VARCHAR(10) DEFAULT NULL COMMENT '请求方法',
  `parentResourceId` VARCHAR(100) DEFAULT NULL COMMENT '父资源ID',
  `resourceLevel` INT NOT NULL DEFAULT 1 COMMENT '资源层级',
  `sortOrder` INT NOT NULL DEFAULT 0 COMMENT '排序顺序',
  `displayName` VARCHAR(100) DEFAULT NULL COMMENT '显示名称',
  `iconClass` VARCHAR(100) DEFAULT NULL COMMENT '图标名',
  `description` VARCHAR(255) DEFAULT NULL COMMENT '资源描述',
  `language` VARCHAR(10) DEFAULT 'zh-CN' COMMENT '语言标识',
  `resourceStatus` VARCHAR(1) NOT NULL DEFAULT 'Y' COMMENT '资源状态(Y启用,N停用)',
  `builtInFlag` VARCHAR(1) NOT NULL DEFAULT 'N' COMMENT '内置资源标记(Y内置,N自定义)',
  `addTime` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `addWho` VARCHAR(32) NOT NULL COMMENT '创建人ID',
  `editTime` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后修改时间',
  `editWho` VARCHAR(32) NOT NULL COMMENT '最后修改人ID',
  `oprSeqFlag` VARCHAR(32) NOT NULL COMMENT '操作序列标识',
  `currentVersion` INT NOT NULL DEFAULT 1 COMMENT '当前版本号',
  `activeFlag` VARCHAR(1) NOT NULL DEFAULT 'Y' COMMENT '活动状态标记(N非活动,Y活动)',
  `noteText` VARCHAR(500) DEFAULT NULL COMMENT '备注信息',
  `extProperty` TEXT DEFAULT NULL COMMENT '扩展属性，JSON格式',
  `reserved1` VARCHAR(64) DEFAULT NULL COMMENT '预留字段1',
  `reserved2` VARCHAR(64) DEFAULT NULL COMMENT '预留字段2',
  `reserved3` VARCHAR(100) DEFAULT NULL COMMENT '预留字段3',
  `reserved4` VARCHAR(100) DEFAULT NULL COMMENT '预留字段4',
  `reserved5` VARCHAR(255) DEFAULT NULL COMMENT '预留字段5',
  PRIMARY KEY (`tenantId`, `resourceId`),
  KEY `IDX_FG_RES_CODE` (`tenantId`, `resourceCode`),
  KEY `IDX_FG_RES_PARENT` (`parentResourceId`),
  KEY `IDX_FG_RES_TYPE` (`resourceType`),
  KEY `IDX_FG_AUTH_RESOURCE_ADD` (`tenantId`, `addTime`)
) ENGINE=InnoDB COMMENT='权限资源表';

